-- E5 contenido: pasos de ejecución + vídeo de técnica (YouTube) por nombre
-- Datos investigados para los 91 ejercicios del seed (generado desde tmp/ingest);
-- aplicación única vía runner (_cf_D1_MIGRATIONS). No repetible por diseño.

UPDATE exercises SET steps = '["Siéntate en la máquina de abducción con la espalda pegada al respaldo y el core activo.", "Coloca la parte externa de las rodillas contra las almohadillas laterales.", "Sujétate a los mangos para mantener el torso estable durante todo el movimiento.", "Separa las rodillas empujando las almohadillas hasta abrir las piernas al máximo que puedas.", "Aprieta los glúteos un segundo en el punto de mayor apertura.", "Cierra las piernas de forma controlada sin dejar que los pesos se golpeen en el recorrido.", "Mantén la espalda neutra y evita levantar las caderas o girar el torso."]', technique_url = 'https://www.youtube.com/watch?v=nw__HpEuKSI' WHERE name = 'Abducción de cadera en máquina';
UPDATE exercises SET steps = '["Túmbate en un banco plano con una mancuerna en cada mano, elevadas sobre el pecho, con palmas enfrentadas y los codos ligeramente flexionados.", "Mantén los codos algo flexionados y fijos para evitar tensión articular durante todo el movimiento.", "Abre los brazos en un arco amplio y controlado, bajando las mancuernas hacia los lados hasta sentir un estiramiento cómodo en el pecho.", "Detén la bajada cuando los codos queden a la altura del torso, sin exceder el rango de comodidad.", "Junta las mancuernas de nuevo por la misma trayectoria, actuando con el pecho y no con los deltoides ni los tríceps.", "No fuerces el estiramiento: ciñete a un rango controlado para proteger el hombro, y mantén el pecho elevado.", "Respira: inhala al abrir y exhala al cerrar los brazos."]', technique_url = 'https://www.youtube.com/watch?v=IHfw7rL_xcQ' WHERE name = 'Aperturas con mancuernas';
UPDATE exercises SET steps = '["Ajusta las poleas a la altura de los hombros o ligeramente por encima y colócate en el centro del crossover con un pie adelantado.", "Agarra una manija con cada mano y adopta una postura estable, con el torso ligeramente inclinado, las rodillas semiflexionadas y los codos apenas flexionados.", "Cruza las manos por delante del pecho, contrayendo el pecho y llevando las manos una hacia la otra.", "Abre los brazos hacia atrás y hacia los lados de manera controlada hasta sentir un estiramiento del pecho, sin bloquear los codos.", "Mantén los hombros bajos y retraídos, y evita impulsar con el torso para no cargar la zona lumbar.", "La fase de apertura es lenta y controlada, la de cierre es firme y contráctil.", "Respira de forma constante: inhala al abrir y exhala al juntar las manos."]', technique_url = 'https://www.youtube.com/watch?v=q1k3bgm-v2A' WHERE name = 'Aperturas en polea (crossover)';
UPDATE exercises SET steps = '["Colócate en cuadrupedia con las manos alineadas bajo los hombros y las rodillas bajo la cadera.", "Mantén la espalda neutra, con el abdomen contraído y la mirada al suelo.", "Extiende el brazo derecho hacia delante a la vez que extiendes la pierna izquierda hacia atrás, formando una línea recta.", "Mantén la cadera paralela al suelo, sin girarla ni hundirla.", "Pausa 1-2 segundos en la extensión completa sintiendo el trabajo del abdomen.", "Vuelve a la posición inicial de forma controlada sin apoyar con brusquedad.", "Alterna con el brazo izquierdo y la pierna derecha manteniendo la respiración continua."]', technique_url = 'https://www.youtube.com/watch?v=my0UbQW4Zco' WHERE name = 'Bird dog';
UPDATE exercises SET steps = '["De pie con las piernas al ancho de las caderas y la barra apoyada sobre los hombros y el trapecio.", "Sujeta la barra con un agarre más ancho que los hombros y saca el pecho y activa el core.", "Con una ligera flexión de rodillas que se mantendrá constante, empuja las caderas hacia atrás.", "Inclina el torso hacia delante manteniendo la espalda completamente neutra.", "Desciende hasta que el torso quede lo más paralelo al suelo posible, si tu flexibilidad lo permite.", "Activa los glúteos y los isquiotibiales para volver a la posición erguida.", "No redondees la espalda: si no mantienes la neutralidad, reduce el rango o el peso."]', technique_url = 'https://www.youtube.com/watch?v=xECk6qrTF5o' WHERE name = 'Buenos días';
UPDATE exercises SET steps = '["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza sin entrelazar los dedos, o cruzadas sobre el pecho.", "Apoya la espalda baja en el suelo y contrae el abdomen antes de comenzar.", "Exhala mientras elevas la cabeza y los hombros del suelo hasta que los omóplatos se despeguen ligeramente.", "Realiza la flexión solo con el abdomen, sin tirar de la cabeza con las manos ni usar el impulso.", "Inhala mientras desciendes de forma controlada hasta que los hombros toquen el suelo.", "Repite las repeticiones indicadas manteniendo la misma velocidad y sin separar la cadera del suelo."]', technique_url = 'https://www.youtube.com/watch?v=hl9Yu7UZqHU' WHERE name = 'Crunch abdominal';
UPDATE exercises SET steps = '["Apoya el pecho y el abdomen sobre un banco inclinado con los brazos colgando extendidos hacia el suelo.", "Agarra una mancuerna con cada mano con agarre supino, con los codos ligeramente separados del banco.", "Exhala y flexiona los codos para subir las mancuernas hacia los hombros, manteniendo los codos fijos en la misma posición.", "Contrae el bíceps en la parte alta y mantén el pecho pegado al banco durante todo el ejercicio.", "Inhala y baja las mancuernas lentamente hasta extender por completo los codos.", "Evita levantar el torso del banco o girar los hombros para generar impulso."]', technique_url = 'https://www.youtube.com/watch?v=iDI78iWgkys' WHERE name = 'Curl araña';
UPDATE exercises SET steps = '["Ponte de pie con la barra delante de los muslos y agarre prono a la anchura de los hombros.", "Sube la barra flexionando los codos y manteniéndolos pegados al tronco.", "Mantén el tronco quieto: el movimiento se limita a la articulación del codo.", "Aprieta el bíceps en la parte alta durante un segundo.", "Baja la barra con control hasta el punto de partida, sin dejar caer el brazo.", "Mantén la espalda recta y el core tenso para evitar usar el impulso del tronco."]', technique_url = 'https://www.youtube.com/watch?v=vq22h2ovm_I' WHERE name = 'Curl con barra';
UPDATE exercises SET steps = '["Ponte de pie con la espalda recta, el pecho erguido y los pies al ancho de los hombros, sosteniendo la barra Z delante de los muslos.", "Agarra la barra por los asideros inclinados con las palmas hacia arriba, a una separación ligeramente mayor que el ancho de los hombros.", "Exhala y flexiona los codos para subir la barra hacia el pecho, manteniendo los codos pegados a los costados.", "Aprieta el bíceps en la parte alta y no dejes que el torso se incline hacia atrás ni la cadera se balancee.", "Inhala y baja la barra de forma controlada hasta extender por completo los codos.", "Realiza el movimiento solo con los antebrazos; si el peso te obliga a balancearte, reduce la carga."]', technique_url = 'https://www.youtube.com/watch?v=tnsI6lqc3kk' WHERE name = 'Curl con barra Z';
UPDATE exercises SET steps = '["Ponte de pie con una mancuerna en cada mano y los brazos a los lados, palmas mirando al cuerpo.", "Flexiona el codo del brazo derecho rotando la muñeca para que la palma mire hacia el techo durante la subida.", "Aprieta el bíceps en la parte alta manteniendo el codo pegado al costado.", "Baja la mancuerna con control hasta la posición inicial.", "Repite con el brazo izquierdo, alternando los brazos en cada repetición.", "Mantén el tronco recto y evita balancearte o inclinarte para ayudar a subir."]', technique_url = 'https://www.youtube.com/watch?v=OLF39uJo9YM' WHERE name = 'Curl con mancuernas alterno';
UPDATE exercises SET steps = '["Siéntate en un banco con las piernas abiertas y apoya el codo del brazo que trabaja contra la cara interna del muslo, manteniendo el brazo extendido hacia abajo.", "Agarra la mancuerna con agarre supino (palma hacia arriba) y mantén el codo pegado al muslo durante todo el movimiento.", "Exhala y flexiona el codo para llevar la mancuerna hacia el hombro, moviendo solo el antebrazo.", "Aprieta el bíceps en la parte alta del recorrido y mantén la contracción un segundo.", "Inhala y baja la mancuerna de forma controlada hasta extender casi por completo el codo, sin soltar la tensión.", "Completa las repeticiones con un brazo y después cambia al otro.", "Evita levantar el codo del muslo o balancear el cuerpo para ayudarte en las repeticiones."]', technique_url = 'https://www.youtube.com/watch?v=FrOJpldJWC4' WHERE name = 'Curl concentrado';
UPDATE exercises SET steps = '["Siéntate en un banco con los antebrazos apoyados en los muslos y las muñecas sobresaliendo más allá de las rodillas.", "Sujeta la barra o las mancuernas con las palmas hacia arriba (agarre supino).", "Baja las muñecas lentamente hasta estirar los antebrazos, dejando que la barra ruede hasta los dedos sin soltarla.", "Contrae los antebrazos y las muñecas para levantar la barra en el rango completo.", "Haz una pausa breve arriba y aprieta los antebrazos al máximo.", "Realiza el movimiento solo con las muñecas, manteniendo los antebrazos fijos contra los muslos.", "Controla el descenso durante 2-3 segundos y repite las repeticiones indicadas."]', technique_url = 'https://www.youtube.com/watch?v=8iMT8heEPtw' WHERE name = 'Curl de muñeca';
UPDATE exercises SET steps = '["Siéntate en un banco con los antebrazos apoyados en los muslos y las muñecas sobresaliendo más allá de las rodillas.", "Sujeta la barra con las palmas hacia abajo (agarre prono), con las manos a la anchura de los hombros.", "Baja las muñecas lentamente hasta estirar la parte superior de los antebrazos.", "Sube las muñecas en dirección a ti elevando el dorso de la mano en el rango completo.", "Haz una pausa breve arriba y contrae la parte superior de los antebrazos.", "Mantén los antebrazos pegados y fijos sobre los muslos, moviendo solo las muñecas.", "Desciende de forma controlada y repite las repeticiones, con pesos moderados para proteger las muñecas."]', technique_url = 'https://www.youtube.com/watch?v=-IT2RyH7QdM' WHERE name = 'Curl de muñeca inverso';
UPDATE exercises SET steps = '["Ajusta el asiento para que la parte trasera de los brazos quede completamente apoyada en el pad.", "Agarra la barra con las palmas hacia arriba y los codos situados en el borde superior del pad.", "Parte con los codos casi extendidos y sube la barra flexionando los codos sin despegarlos del pad.", "Aprieta el bíceps en la parte alta y evita levantar los codos o usar rebote.", "Baja lentamente hasta dejar los codos casi extendidos, aguantando la tensión en la fase excéntrica.", "Mantén la espalda recta y el pecho alto durante toda la serie."]', technique_url = 'https://www.youtube.com/watch?v=wUX_jliIj3o' WHERE name = 'Curl en banco Scott';
UPDATE exercises SET steps = '["Coloca la polea en la posición más baja y monta una barra recta o una cuerda en el gancho.", "Ponte de pie frente a la máquina con un pie ligeramente adelantado y agarra el implemento con las palmas hacia arriba.", "Mantén los codos pegados al tronco y sube el peso flexionando solo los codos.", "Aprieta el bíceps en la parte alta y evita mover el tronco para tomar impulso.", "Baja el peso con control hasta extender por completo los codos.", "Mantén las muñecas en línea con el antebrazo y un ritmo constante durante la serie."]', technique_url = 'https://www.youtube.com/watch?v=OGI2K-Qc2z0' WHERE name = 'Curl en polea';
UPDATE exercises SET steps = '["Colócate de pie frente a la máquina de curl femoral y apoya el muslo de la pierna que trabaja en la almohadilla.", "Ajusta el rodillo en la parte posterior del tobillo, por encima del tendón de Aquiles.", "Sujétate al soporte con las manos para mantener el torso estable y balancearte lo mínimo.", "Flexiona la rodilla llevando el talón hacia el glúteo con la cadera extendida.", "Mantén el muslo apoyado en la almohadilla y la pelvis sin inclinarse hacia delante.", "Baja la pierna lentamente hasta extender la rodilla por completo.", "Realiza todas las repeticiones con una pierna y cambia a la otra."]', technique_url = 'https://www.youtube.com/watch?v=yALEL1XnhZE' WHERE name = 'Curl femoral de pie';
UPDATE exercises SET steps = '["Siéntate en la máquina de curl femoral y ajusta el asiento para que la rodilla quede alineada con el eje de giro.", "Coloca los rodillos en la parte posterior de los tobillos, justo encima del talón.", "Asegura los muslos contra el asiento con el cojín de sujeción y agárrate a los mangos.", "Flexiona las rodillas todo lo que puedas llevando los talones hacia abajo y atrás.", "Aprieta los isquiotibiales en el punto más corto del recorrido.", "Extiende las piernas lentamente hasta la posición inicial sin bloquear las rodillas con fuerza.", "Evita levantar la cadera del asiento y controla el peso en ambas fases."]', technique_url = 'https://www.youtube.com/watch?v=CBCPBnMzsMI' WHERE name = 'Curl femoral sentado';
UPDATE exercises SET steps = '["Túmbate boca abajo en la máquina de curl femoral con las rodillas alineadas con el eje del aparato.", "Engancha los talones por debajo de los rodillos y sujeta los agarres laterales.", "Mantén las caderas y el torso pegados al banco para evitar que se levanten.", "Flexiona las rodillas llevando los talones hacia los glúteos con un movimiento controlado.", "Aprieta los isquiotibiales en la parte alta del movimiento.", "Baja las piernas lentamente hasta estirar por completo las rodillas sin perder tensión.", "Exhala al flexionar, inhala al bajar, y evita usar el impulso de la cadera."]', technique_url = 'https://www.youtube.com/watch?v=kmtn5RJkvVE' WHERE name = 'Curl femoral tumbado';
UPDATE exercises SET steps = '["Siéntate en un banco reclinado a unos 45-60 grados con la espalda y la cabeza apoyadas en el respaldo.", "Agarra una mancuerna con cada mano, con agarre supino, y deja los brazos colgando extendidos a los lados del cuerpo.", "Exhala y flexiona ambos codos para llevar las mancuernas hacia los hombros sin adelantarlas ni mover los codos.", "Mantén los codos quietos y contrae al máximo el bíceps en la parte alta.", "Inhala y baja las mancuernas con control hasta extender por completo los codos, sintiendo el estiramiento del bíceps.", "No arquees la espalda ni eleves los hombros: el movimiento debe ser solo de los antebrazos."]', technique_url = 'https://www.youtube.com/watch?v=nw2Y9iHHzlU' WHERE name = 'Curl inclinado con mancuernas';
UPDATE exercises SET steps = '["Ponte de pie con una mancuerna en cada mano y las palmas enfrentadas en agarre neutro.", "Sube las mancuernas flexionando los codos y manteniendo las palmas enfrentadas durante todo el recorrido.", "Aprieta el bíceps junto a la parte superior del antebrazo en la parte alta.", "Baja las mancuernas con control hasta extender por completo los codos.", "Mantén los codos fijos al costado y el tronco recto, sin balancearte.", "Puedes alternar brazos o subir ambos a la vez; conserva un ritmo controlado."]', technique_url = 'https://www.youtube.com/watch?v=znTSJ_2zJN0' WHERE name = 'Curl martillo';
UPDATE exercises SET steps = '["Túmbate boca arriba con los brazos extendidos hacia el techo y las rodillas flexionadas en ángulo de 90 grados.", "Eleva las piernas de forma que las rodillas queden alineadas sobre la cadera y la espalda baja pegada al suelo.", "Contrae el abdomen para presionar la zona lumbar contra el suelo durante todo el ejercicio.", "Exhala y extiende el brazo derecho por encima de la cabeza mientras bajas la pierna izquierda extendida sin tocar el suelo.", "Haz una pausa breve en el punto más bajo sin arquear la espalda.", "Inhala y vuelve el brazo y la pierna a la posición inicial de forma controlada.", "Alterna con el brazo izquierdo y la pierna derecha, repitiendo las repeticiones indicadas."]', technique_url = 'https://www.youtube.com/watch?v=aGy7ilK9rg4' WHERE name = 'Dead bug';
UPDATE exercises SET steps = '["Cuélgate de la barra con un agarre prono a la anchura de los hombros y brazos extendidos.", "Activa los hombros bajándolos de las orejas y contrae el abdomen para estabilizar el cuerpo.", "Tira de los codos hacia el suelo y hacia atrás para impulsar el pecho hacia la barra.", "Sube hasta que el mentón supere la barra o el pecho quede a su altura, según tu nivel.", "Exhala durante la subida y evita balancear las piernas ni usar impulso.", "Baja de forma lenta y controlada hasta que los brazos queden completamente extendidos.", "Inhala durante el descenso y repite las repeticiones indicadas manteniendo el cuerpo firme y alineado."]', technique_url = 'https://www.youtube.com/watch?v=-31tCeBwPV0' WHERE name = 'Dominada con agarre';
UPDATE exercises SET steps = '["Cuelga de la barra con agarre prono (palmas hacia el frente), con las manos separadas algo más que la anchura de hombros.", "Retrae los hombros y activa la zona media antes de empezar el movimiento, desde la posición de brazos extendidos.", "Tira de la barra hasta que el mentón supere y la barbilla quede por encima de la línea de la barra, con el pecho hacia arriba.", "Baja el cuerpo de forma controlada hasta los brazos casi extendidos, evitando balancearte y manteniendo el movimiento limpio.", "Mantén el torso estable, sin tirar con fuerza del cuello; el esfuerzo principal proviene de la espalda y el dorsal.", "Controla la fase excéntrica (bajada) al menos tan lentamente como la subida y no pierdas la tensión.", "Respira: exhala al subir e inhala al bajar. Si no dominas el ejercicio, usar un asistente o banda elástica.", "Añade peso o variantes de agarre para progresar cuando completes series de 10 repeticiones o más."]', technique_url = 'https://www.youtube.com/watch?v=94LjCdfkQ-0' WHERE name = 'Dominadas';
UPDATE exercises SET steps = '["Cuelga de la barra con agarre supino y las manos separadas a la anchura de los hombros, con las palmas hacia ti.", "Activa abdomen y lumbares para mantener el cuerpo estable y sin balanceo excesivo, partiendo de brazos extendidos.", "Tira de la barra con los brazos hasta que la barbilla supere la línea de la barra, acercando el pecho hacia ella.", "Baja el cuerpo de forma controlada hasta los brazos casi extendidos, manteniendo la tensión y sin dejar caer los hombros.", "Mantén los codos cerca del cuerpo y los hombros hacia atrás, evitando que suban hacia las orejas.", "Respira: exhala al subir e inhala al bajar.", "Si la fuerza no alcanza, usa una banda elástica o una máquina asistida para progresar."]', technique_url = 'https://www.youtube.com/watch?v=T9jzUiMtZbk' WHERE name = 'Dominadas supinas';
UPDATE exercises SET steps = '["Ponte de pie con las mancuernas delante de los muslos y las palmas mirando hacia atrás.", "Levanta una mancuerna hacia delante manteniendo el codo casi extendido.", "Detén el recorrido a la altura de los hombros, sin elevarla más ni tomar impulso.", "Baja la mancuerna con control hasta el muslo.", "Alterna los brazos en cada repetición manteniendo el tronco recto y sin balancearte."]', technique_url = 'https://www.youtube.com/watch?v=g58tMyz5Pro' WHERE name = 'Elevaciones frontales';
UPDATE exercises SET steps = '["Ponte de pie con una mancuerna en cada mano a los lados, los brazos relajados y las palmas mirando al cuerpo.", "Sube las mancuernas lateralmente en un arco hasta la altura de los hombros.", "Mantén los codos ligeramente flexionados y deja que la parte alta del brazo lidere el movimiento.", "Detén la elevación a la altura de los hombros, sin subir por encima ni girar el torso.", "Baja las mancuernas con control hasta la posición inicial.", "Pausa un segundo arriba y usa un peso que no obligue a rebotes ni a balancearse."]', technique_url = 'https://www.youtube.com/watch?v=aVa9ce3SlSA' WHERE name = 'Elevaciones laterales';
UPDATE exercises SET steps = '["Ponte de pie sobre el borde de un escalón o plataforma con la punta de un pie apoyada y el talón sobresaliendo al vacío.", "Sujétate a una pared o barra con una mano para mantener el equilibrio.", "Levanta la otra pierna del suelo y cruza el pie libre por detrás del tobillo de la pierna de trabajo.", "Baja el talón lentamente hasta estirar por completo el gemelo, sintiendo un estiramiento profundo.", "Eleva el talón lo más alto posible empujando con la punta del pie, como si quisieras pisar el techo.", "Pausa un segundo arriba y contrae el gemelo al máximo.", "Baja de forma controlada en 2-3 segundos y repite el número de repeticiones indicado sin perder el equilibrio.", "Cambia de pierna y repite con la misma cantidad de repeticiones en ambas."]', technique_url = 'https://www.youtube.com/watch?v=9Xbg8oAk_-Y' WHERE name = 'Elevación de gemelos a una pierna';
UPDATE exercises SET steps = '["Colócate de pie con el antepié sobre un escalón o plataforma y los talones colgando fuera del borde.", "Sujétate a un soporte con las manos para mantener el equilibrio.", "Baja los talones lentamente hasta sentir un estiramiento completo de los gemelos.", "Empuja con la punta del pie y eleva los talones lo más alto posible.", "Haz una pausa de un segundo en la parte alta apretando los gemelos.", "Desciende de forma lenta y controlada hasta el estiramiento máximo.", "Mantén las rodillas extendidas y evita usar el impulso con el cuerpo."]', technique_url = 'https://www.youtube.com/watch?v=Ogk_k5cx0FQ' WHERE name = 'Elevación de gemelos de pie';
UPDATE exercises SET steps = '["Sitúate en la prensa de piernas con la espalda y los hombros apoyados en el respaldo.", "Coloca las puntas de los pies en la parte baja de la plataforma y deja los talones sobresaliendo fuera del borde.", "Desbloquea y baja la plataforma hasta que las rodillas queden ligeramente flexionadas, sin llegar a bloquearlas.", "Baja los talones lentamente hasta estirar al máximo los gemelos, sintiendo tensión en la parte posterior de la pierna.", "Empuja con las puntas de los pies para subir la plataforma en el rango completo, elevando los talones lo más alto posible.", "Realiza una pausa breve arriba, contrayendo los gemelos al máximo.", "Desciende de forma controlada durante 2-3 segundos y repite el movimiento manteniendo las rodillas fijas en todo momento.", "Al terminar, apoya firmemente los talones y bloquea el seguro antes de retirar la carga."]', technique_url = 'https://www.youtube.com/watch?v=EmRyV5tKZN8' WHERE name = 'Elevación de gemelos en prensa';
UPDATE exercises SET steps = '["Siéntate en la máquina de gemelos con la espalda recta y la cadera flexionada a 90 grados.", "Coloca el antepié sobre la plataforma con los talones colgando en el borde.", "Ajusta el peso sobre las rodillas y sujétalo con los muslos en la posición.", "Baja los talones lentamente hasta estirar por completo el sóleo.", "Empuja con los antepiés y eleva los talones todo lo que puedas.", "Haz una pausa corta en la parte alta apretando los gemelos.", "Desciende de forma controlada, sin rebotar en el estiramiento, y repite."]', technique_url = 'https://www.youtube.com/watch?v=rfkYC-mbQus' WHERE name = 'Elevación de gemelos sentado';
UPDATE exercises SET steps = '["Cuélgate de la barra con agarre prono a la anchura de los hombros y brazos extendidos.", "Contrae el abdomen y los glúteos para evitar que el tronco oscile antes de empezar.", "Exhala y eleva las piernas rectas hasta que queden paralelas al suelo o más arriba, según el nivel.", "Rota ligeramente la cadera hacia atrás al subir para activar la parte baja del abdomen.", "Haz una pausa breve arriba sin balancear el cuerpo.", "Baja las piernas de forma lenta y controlada hasta el agarre inicial.", "Mantén una respiración constante y frena el balanceo contrayendo el abdomen durante toda la serie."]', technique_url = 'https://www.youtube.com/watch?v=XU6jtDCiNKI' WHERE name = 'Elevación de piernas colgado';
UPDATE exercises SET steps = '["Ajusta la polea en la posición más baja y colócate de lateral al aparato, con el asa en la mano exterior.", "Ponte de pie con el tronco erguido y el pie contrario ligeramente adelantado para estabilizar.", "Con el brazo casi extendido, levanta el asa en un arco lateral hasta la altura del hombro.", "Mantén los codos ligeramente flexionados y los hombros bajos durante la subida.", "Baja el asa con control hasta la posición inicial sin dejar que el peso tire del hombro.", "Evita balancearte o girar el cuerpo para ayudar a subir el peso."]', technique_url = 'https://www.youtube.com/watch?v=jp070OTX3pA' WHERE name = 'Elevación lateral en polea';
UPDATE exercises SET steps = '["Sostén la barra con las manos separadas a la anchura de los hombros, con las palmas mirando hacia atrás.", "Ponte de pie con la espalda neutra, los hombros hacia abajo y los brazos extendidos a los costados.", "Sube los hombros hacia las orejas mientras exhalas, elevándolos lo más alto posible.", "Mantén la posición un segundo arriba, con el cuello relajado y sin flexionar los brazos.", "Baja los hombros con control hasta la posición inicial.", "Evita girar los hombros hacia atrás y los tirones: el movimiento es solo hacia arriba y abajo."]', technique_url = 'https://www.youtube.com/watch?v=qXlzUyVKNKY' WHERE name = 'Encogimientos con barra';
UPDATE exercises SET steps = '["Colócate de pie frente a una caja o banco estable a la altura de la rodilla.", "Apoya el pie completo de la pierna que trabaja sobre el escalón.", "Empuja con el talón del pie apoyado y sube el cuerpo hasta quedar de pie sobre el escalón.", "Lleva la pierna contraria hacia delante sin apoyar el pie en el escalón si buscas trabajo de glúteo.", "Desciende controlando con la pierna de apoyo y baja el pie contrario hasta el suelo.", "Mantén el core activo, el torso erguido y la rodilla de apoyo alineada con el pie durante todo el movimiento.", "Completa todas las repeticiones con una pierna antes de cambiar a la otra."]', technique_url = 'https://www.youtube.com/watch?v=CpKJ1B4iNwc' WHERE name = 'Escalón';
UPDATE exercises SET steps = '["Ponte de pie frente a la polea alta con el torso ligeramente inclinado y agarra la cuerda con las palmas enfrentadas.", "Coloca los codos pegados a los costados, con los antebrazos formando un ángulo de 90 grados con el brazo.", "Exhala y extiende los codos hacia abajo separando las puntas de la cuerda hacia los lados al final del recorrido.", "Aprieta el tríceps en la parte baja manteniendo los codos fijos al torso.", "Inhala y sube la cuerda con control hasta la posición inicial sin separar los codos del cuerpo.", "Evita arquear la espalda o desplazar los hombros para empujar con más peso del que maneja el tríceps."]', technique_url = 'https://www.youtube.com/watch?v=HAS8uy73HqM' WHERE name = 'Extensión con cuerda';
UPDATE exercises SET steps = '["Siéntate en la máquina de extensiones con las rodillas alineadas con el eje de giro de la palanca.", "Coloca los rodillos sobre la parte baja de las espinillas, justo encima de los tobillos, y sujeta las asas del asiento.", "Exhala y extiende las rodillas hasta enderezar por completo las piernas, elevando el peso.", "Mantén un segundo de contracción del cuádriceps en la parte alta, sin levantar las caderas del asiento.", "Inhala y baja el peso con control hasta la posición inicial, sin dejar que caiga de golpe.", "No arquees la espalda ni te ayudes con impulso del cuerpo para levantar el peso."]', technique_url = 'https://www.youtube.com/watch?v=DI34ngDC8FU' WHERE name = 'Extensión de cuádriceps';
UPDATE exercises SET steps = '["Ponte de pie frente a la polea alta con el torso ligeramente inclinado hacia delante y los pies firmes.", "Agarra la barra con agarre prono (palmas hacia abajo) a la altura de los hombros, con los codos pegados al torso.", "Exhala y extiende los codos para empujar la barra hacia abajo hasta extender por completo los brazos.", "Aprieta el tríceps abajo, sin separar los codos del cuerpo.", "Inhala y sube la barra con control hasta que los antebrazos queden por encima del paralelo, sin dejar que la barra suba de golpe.", "Evita inclinar el torso o mover los hombros para ayudarte; el movimiento es solo de los antebrazos."]', technique_url = 'https://www.youtube.com/watch?v=FA8TyV_eF8M' WHERE name = 'Extensión en polea';
UPDATE exercises SET steps = '["Siéntate en un banco con respaldo o ponte de pie con la espalda recta y sujeta una mancuerna con ambas manos en forma de campana.", "Eleva la mancuerna sobre la cabeza extendiendo los brazos, con las palmas empujando el interior del disco.", "Inhala y flexiona los codos para bajar la mancuerna por detrás de la cabeza, manteniendo los codos apuntando hacia delante y pegados.", "Baja hasta la altura de la nuca o hasta sentir un estiramiento completo del tríceps.", "Exhala y extiende los codos para volver a la posición inicial sin arquear la zona lumbar.", "No separes los codos hacia los lados: apuntan siempre hacia delante."]', technique_url = 'https://www.youtube.com/watch?v=fQ-KB40W3d8' WHERE name = 'Extensión sobre cabeza';
UPDATE exercises SET steps = '["Ajusta la polea a la altura de los ojos y coloca una cuerda en el gancho.", "Agarra la cuerda con las palmas enfrentadas y da un paso atrás hasta tensar el cable.", "Lleva la cuerda hacia la cara apuntando con los codos altos y separados.", "Separa las manos de la cuerda al final del recorrido, rotando los brazos hacia fuera.", "Aprieta los trapecios inferiores y los rotadores del hombro y mantén un segundo la contracción.", "Estira los brazos de vuelta con control hasta la posición inicial."]', technique_url = 'https://www.youtube.com/watch?v=X-xCQ1gh-kA' WHERE name = 'Face pull';
UPDATE exercises SET steps = '["Colócate entre las mancuernas o pesas con los pies a la anchura de los hombros.", "Agarra las pesas con las palmas hacia adentro y levántalas con la espalda recta hasta colgarlas a los costados.", "Endereza el cuerpo, eleva el pecho y contrae el abdomen, con los hombros hacia atrás y abajo.", "Camina en línea recta dando pasos cortos y firmes, manteniendo el cuerpo erguido y sin inclinarte hacia un lado.", "Sujeta las pesas con fuerza pero con los brazos relajados, dejando que cuelguen de forma natural.", "No balancees el torso: mueve la cadera con pasos controlados y la cabeza alta.", "Camina la distancia indicada hasta guardar las pesas, dejándolas en el suelo con la espalda recta."]', technique_url = 'https://www.youtube.com/watch?v=kj5F1t6mLF4' WHERE name = 'Farmer carry';
UPDATE exercises SET steps = '["Colócate en posición de plancha con las manos apoyadas en el suelo, algo más separadas que los hombros y alineadas con el cuerpo.", "Alinea cabeza, columna (cuerpo rígido) y piernas, con los glúteos y el abdomen firmes para evitar que caiga la cadera.", "Baja el cuerpo de forma controlada flexionando los codos hacia atrás, hasta que el pecho esté a unos 3-5 cm del suelo, sin arquear la espalda.", "Empuja el suelo con fuerza extendiendo los codos, manteniendo el cuerpo en línea recta durante todo el recorrido.", "Puedes variar la dificultad: rodillas apoyadas para facilitar el movimiento, o pies elevados para intensificarlo.", "Controla la fase de bajada y no pierdas el pecho; el recorrido completo es mejor que un número alto de repeticiones parciales.", "Repite el gesto de manera continua y con el abdomen firme en cada repetición."]', technique_url = 'https://www.youtube.com/watch?v=b2UagYWNErY' WHERE name = 'Flexiones';
UPDATE exercises SET steps = '["Colócate en posición de plancha con las manos juntas bajo el pecho, formando un rombo con los pulgares e índices de ambas manos.", "Extiende las piernas y mantén el cuerpo recto de la cabeza a los talones, con el abdomen activo.", "Inhala y baja el pecho flexionando los codos, que deben quedar pegados al cuerpo, hasta casi tocar el suelo.", "Exhala y empuja contra el suelo para subir hasta extender por completo los codos.", "Mantén la cadera firme para que no caiga ni se eleve durante el movimiento.", "Si no puedes mantener la plancha de pie, apoya las rodillas en el suelo y realiza las flexiones desde ahí."]', technique_url = 'https://www.youtube.com/watch?v=NO3fnbQr5nk' WHERE name = 'Flexiones diamante';
UPDATE exercises SET steps = '["Siéntate en el borde de un banco y apoya las palmas de las manos en el borde, a ambos lados de las caderas.", "Desliza las caderas fuera del banco con las piernas extendidas y los brazos rectos, sujetando el peso del cuerpo.", "Inhala y flexiona los codos hacia atrás para bajar el cuerpo hasta que los codos formen un ángulo de 90 grados.", "Mantén el torso cerca del banco y la espalda a poca distancia de él, sin bajar en exceso los hombros.", "Exhala y empuja con los tríceps para subir hasta extender por completo los codos.", "Si resulta difícil, dobla las rodillas y apoya los talones en el suelo para reducir la resistencia; para dificultarlo, eleva los pies en otro banco."]', technique_url = 'https://www.youtube.com/watch?v=bR9d6yRH3iA' WHERE name = 'Fondos en banco';
UPDATE exercises SET steps = '["Colócate entre dos barras paralelas y sostente sobre ellas con los brazos extendidos y el cuerpo alineado.", "Aprieta el torso de manera optativa llevando las piernas cruzadas hacia atrás e inclina ligeramente el cuerpo hacia delante para enfatizar el pecho.", "Baja el cuerpo de forma controlada flexionando los codos hacia atrás, hasta que los codos queden a unos 90 grados y los hombros por debajo de los codos.", "Evita bajar por debajo del nivel de comodidad; la altura del banco en paralelas flexibles marca el rango seguro.", "Sube con fuerza extendiendo los codos hasta casi la posición rígida, sin balancear el cuerpo.", "Mantén codos pegados al torso para no cargar el hombro, y la zona media activa y estable.", "Respira de forma controlada: inhala al bajar y exhala al subir."]', technique_url = 'https://www.youtube.com/watch?v=d8IEGU9BrLU' WHERE name = 'Fondos en paralelas';
UPDATE exercises SET steps = '["Túmbate boca arriba con los glúteos cerca de una pared, sin llegar a tocarla.", "Flexiona las rodillas y coloca las plantas de los pies juntas, dejando caer las rodillas hacia los lados como una rana.", "Aprieta los glúteos y eleva las caderas del suelo hacia la pared.", "Lleva los talones contra la pared en la parte alta, manteniendo las rodillas abiertas.", "Haz una pausa corta apretando con fuerza los glúteos.", "Baja las caderas de forma controlada pero manteniendo la tensión en el glúteo.", "Realiza series con un movimiento continuo y corto, similar a un bumbazo."]', technique_url = 'https://www.youtube.com/watch?v=lAwMsvDsVcE' WHERE name = 'Frog pump';
UPDATE exercises SET steps = '["Apoya el torso sobre un banco de modo que los hombros queden sobre el borde y los glúteos en el aire.", "Coloca los pies en el suelo al ancho de los hombros, cerca de los glúteos, con los talones firmes.", "Apoya la barra o el peso sobre la cadera y sujétala con las manos para estabilizarla.", "Activa el core y levanta las caderas empujando con los talones hasta extender por completo la cadera.", "En la posición alta, la cadera debe estar extendida y el torso en línea con los muslos.", "Aprieta los glúteos un segundo en la parte alta sin arquear la espalda.", "Baja las caderas de forma controlada hasta que los glúteos rocen el suelo y repite."]', technique_url = 'https://www.youtube.com/watch?v=lmUx6WAV-BQ' WHERE name = 'Hip thrust';
UPDATE exercises SET steps = '["Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas estiradas.", "Eleva los hombros, los brazos y las piernas del suelo a la vez, manteniendo la espalda baja pegada al suelo.", "Comprime el abdomen con fuerza para presionar la zona lumbar contra el suelo.", "Mantén los brazos junto a las orejas y las piernas rectas, con los pies juntos y apuntando hacia delante.", "Forma una ligera curva en forma de plátano y mantén la posición sin arquear la cadera.", "Respira de forma continua sin aguantar el aire y sin que la espalda baja se despegue del suelo.", "Mantén el tiempo indicado; si la espalda se arquea, flexiona ligeramente las rodillas hasta recuperar el control."]', technique_url = 'https://www.youtube.com/watch?v=E58napCEGEw' WHERE name = 'Hollow body hold';
UPDATE exercises SET steps = '["Siéntate en la máquina de jalón con las rodillas sujetadas por los rodillos y el torso erguido, con los hombros retraídos.", "Agarra la barra con las manos algo más separadas que los hombros, con los brazos extendidos por encima de la cabeza.", "Tira de la barra hacia la parte alta del pecho, llevando los codos hacia abajo y atrás, juntando las escápulas sin inclinar el torso hacia atrás.", "Extiende los brazos de forma controlada dejando que la barra suba hasta casi estirarse, sin perder la tensión en la espalda.", "Evita el balanceo: tira con la espalda y los dorsales, no basculando el tronco, y evita que la barra golpee el pecho con fuerza.", "Mantén la espalda recta y el abdomen activo durante todo el movimiento.", "Respira: exhala al tirar de la barra e inhala al devolverla."]', technique_url = 'https://www.youtube.com/watch?v=x2Y6Mb41zjY' WHERE name = 'Jalón al pecho';
UPDATE exercises SET steps = '["Colócate en posición de plancha alta, con las manos bajo los hombros, los brazos extendidos y el cuerpo en línea recta.", "Contrae el abdomen y mantén la cadera baja, sin levantarla ni hundirla durante el ejercicio.", "Lleva una rodilla hacia el pecho con un movimiento rápido y controlado.", "Extiende esa pierna hacia atrás mientras llevas la rodilla contraria hacia el pecho.", "Alterna las piernas a ritmo constante, como si corrieras en el suelo, apoyando solo las puntas de los pies.", "Mantén la cabeza neutra y la mirada hacia el suelo, sin levantar la cadera.", "Realiza el tiempo indicado manteniendo el ritmo y sin dejar de contraer el abdomen."]', technique_url = 'https://www.youtube.com/watch?v=XWlDAy4_Dvw' WHERE name = 'Mountain climbers';
UPDATE exercises SET steps = '["Arrodíllate con las rodillas a la anchura de las caderas y el torso erguido.", "Pide a un compañero que sujete firmemente los tobillos o fija las piernas bajo un aparato anclado.", "Cruza los brazos sobre el pecho y activa el core para bloquear la cadera.", "Baja el torso hacia delante lo más lentamente posible, extendiendo las rodillas mientras el cuerpo gira.", "Evita que la cadera se extienda o se doble: el movimiento es solo de rodilla.", "Cuando no puedas frenar más, amortigua la caída con las manos en el suelo.", "Empuja con los brazos o pide ayuda para volver a la posición inicial, o usa una banda de asistencia."]', technique_url = 'https://www.youtube.com/watch?v=1hI731-sQd0' WHERE name = 'Nordic curl';
UPDATE exercises SET steps = '["Coloca la correa del tobillo y ajústala a la polea baja, de espaldas a la máquina.", "Apóyate en el soporte o la máquina con los brazos y el torso estable, con una ligera inclinación hacia delante.", "Sobre la pierna de trabajo, inicia el movimiento con el glúteo y extiende la cadera llevando la pierna atrás.", "Sube la pierna al máximo sin arquear la espalda baja ni balancear el cuerpo.", "Haz una pausa corta en el punto de máxima contracción del glúteo.", "Baja la pierna de forma controlada hasta el punto inicial, sin que el peso toque el soporte.", "Completa las repeticiones con una pierna y luego cambia a la otra."]', technique_url = 'https://www.youtube.com/watch?v=5jJ3CxVTAas' WHERE name = 'Patada de glúteo en polea';
UPDATE exercises SET steps = '["Inclina el torso hacia delante con la espalda recta, las rodillas ligeramente flexionadas y una mancuerna en cada mano.", "Lleva los brazos al costado del cuerpo con los codos doblados y pegados al torso, de modo que los antebrazos queden hacia el suelo.", "Exhala y extiende los codos hacia atrás hasta que los brazos queden paralelos al suelo, sin mover los hombros.", "Mantén el brazo extendido un segundo y aprieta el tríceps.", "Inhala y regresa con control a la posición inicial, sin dejar que el codo caiga ni que el torso se enderece.", "Usa un peso ligero y evita balancear el cuerpo para no implicar la zona lumbar."]', technique_url = 'https://www.youtube.com/watch?v=i_38xEoC5wA' WHERE name = 'Patada de tríceps';
UPDATE exercises SET steps = '["Colócate detrás de la barra con los pies a la anchura de las caderas y la barra sobre el empeine.", "Flexiona caderas y rodillas para agarrar la barra con las manos separadas a la anchura de los hombros.", "Coloca la espalda neutra, el pecho hacia delante y los hombros ligeramente por delante de la barra.", "Tensa el core y empuja el suelo con los pies para despegar la barra manteniéndola pegada a las piernas.", "Extiende caderas y rodillas a la vez hasta quedar erguido, con la cadera bloqueada y la barra rozando los muslos.", "Baja la barra flexionando primero las caderas y empujando los glúteos hacia atrás, con la espalda recta.", "Termina el descenso en el punto de partida con control, sin rebotar contra el suelo."]', technique_url = 'https://www.youtube.com/watch?v=0XL4cZR2Ink' WHERE name = 'Peso muerto';
UPDATE exercises SET steps = '["De pie con los pies al ancho de las caderas y las rodillas casi completamente extendidas, sin bloquearlas.", "Sujeta la barra o las mancuernas con las manos a la anchura de los hombros.", "Con la espalda neutra, empuja las caderas hacia atrás y baja el peso siguiendo las piernas.", "Desciende hasta que sientas un estiramiento intenso en los isquiotibiales, sin redondear la espalda.", "Mantén la barra pegada al cuerpo y los hombros por encima de la cadera.", "Sube llevando las caderas hacia delante y apretando los glúteos hasta la posición inicial.", "No sobrepases el rango que te permita mantener la espalda recta."]', technique_url = 'https://www.youtube.com/watch?v=L08xrzn_ahk' WHERE name = 'Peso muerto con piernas rectas';
UPDATE exercises SET steps = '["De pie con las piernas al ancho de las caderas y una ligera flexión de rodillas que se mantendrá fija.", "Sujeta la barra o las mancuernas al frente de los muslos con un agarre a la anchura de los hombros.", "Con la espalda neutra, empuja las caderas hacia atrás deslizando el peso por delante de los muslos.", "Desciende las pesas hasta mitad de la espinilla o hasta donde mantengas la espalda recta.", "Mantén los hombros hacia atrás, el pecho erguido y las rodillas casi extendidas.", "Activa los glúteos y lleva las caderas hacia delante para volver a la posición erguida.", "Aprieta los glúteos en la parte alta sin hiperextender la lumbar y repite."]', technique_url = 'https://www.youtube.com/watch?v=99aPIw8XxRg' WHERE name = 'Peso muerto rumano';
UPDATE exercises SET steps = '["De pie, coloca el peso sobre una pierna y extiende la otra pierna hacia delante, ligeramente elevada del suelo.", "Extiende los brazos hacia delante para equilibrarte y mantén el pecho erguido y la espalda neutra.", "Flexiona la rodilla de apoyo y baja el cuerpo controlando la cadera hacia atrás.", "Desciende hasta que el glúteo quede cerca del talón, con el talón de apoyo siempre en el suelo.", "Mantén el pie de apoyo completamente apoyado y la rodilla alineada con el pie.", "Empuja con el glúteo y el cuádriceps para subir a la posición inicial sin balanceos.", "Si no logras el rango completo, apóyate en un compañero, una pared o una banda."]', technique_url = 'https://www.youtube.com/watch?v=XZR_jZ6L67U' WHERE name = 'Pistol squat';
UPDATE exercises SET steps = '["Colócate en el suelo apoyando los antebrazos, con los codos alineados justo debajo de los hombros.", "Extiende las piernas hacia atrás y apoya las puntas de los pies en el suelo.", "Forma una línea recta desde la cabeza hasta los talones, sin arquear la espalda ni levantar la cadera.", "Contrae el abdomen y los glúteos para estabilizar el tronco durante todo el ejercicio.", "Mantén la cabeza neutra, con la mirada al suelo entre las manos, evitando mirar hacia delante.", "Respira de forma continua y tranquila sin aguantar la respiración.", "Mantén la posición el tiempo indicado; si la cadera empieza a hundirse, finaliza la serie."]', technique_url = 'https://www.youtube.com/watch?v=AD1YG9b88bk' WHERE name = 'Plancha';
UPDATE exercises SET steps = '["Túmbate de lado y apoya el antebrazo en el suelo, con el codo alineado debajo del hombro.", "Apila las piernas una sobre otra y apoya la cara externa del pie inferior en el suelo.", "Eleva la cadera hasta formar una línea recta desde la cabeza hasta los pies.", "Contrae el abdomen y el glúteo del lado apoyado para impedir que la cadera se hunda.", "Mantén el hombro activo, empujando el suelo con el antebrazo como si quisieras alejar el cuerpo.", "Mantén la posición el tiempo indicado respirando con normalidad.", "Cambia de lado y repite el mismo tiempo con el otro brazo."]', technique_url = 'https://www.youtube.com/watch?v=kyOeSuh7LLo' WHERE name = 'Plancha lateral';
UPDATE exercises SET steps = '["Siéntate en la máquina de prensa y coloca los pies en la plataforma al ancho de los hombros, con las puntas ligeramente hacia fuera.", "Agarra las asas laterales y mantén la zona lumbar y la cadera pegadas al respaldo y al asiento.", "Suelta los seguros y baja la plataforma flexionando las rodillas de forma controlada.", "Baja hasta que las rodillas formen un ángulo de 90 grados o la movilidad lo permita, sin que la cadera se despegue del asiento.", "Empuja la plataforma extendiendo las rodillas sin bloquearlas por completo en la parte alta.", "No redondees la espalda durante el recorrido: la zona lumbar siempre queda apoyada."]', technique_url = 'https://www.youtube.com/watch?v=bNsrqXUIJqc' WHERE name = 'Prensa de pierna';
UPDATE exercises SET steps = '["Siéntate con la espalda apoyada en el respaldo y sujeta las mancuernas a la altura de los hombros con las palmas mirando hacia ti.", "Empuja las mancuernas hacia arriba rotando las muñecas para que las palmas miren hacia delante al final del recorrido.", "Extiende por completo los codos sobre la cabeza sin arquear la lumbar ni rebotar.", "Baja las mancuernas invirtiendo la rotación hasta que las palmas vuelvan a mirar hacia ti.", "Mantén el core tenso y los pies firmes durante todas las repeticiones."]', technique_url = 'https://www.youtube.com/watch?v=V8GcUp4COLg' WHERE name = 'Press Arnold';
UPDATE exercises SET steps = '["Túmbate en el banco con los ojos bajo la barra y los pies firmemente apoyados en el suelo.", "Agarra la barra algo más ancha que los hombros, con el pulgar alrededor, y retrae las escápulas para arquear ligeramente la zona media de la espalda.", "Descuélgala y bájala controlada hacia el pecho, con los codos formando un ángulo de unos 45 grados con el torso hasta rozar la línea media del pecho.", "Empuja la barra hacia arriba en línea ligeramente descendente hasta extender los codos sin bloquearlos con fuerza excesiva.", "Mantén la espalda baja pegada al banco, los hombros retraídos y los codos fijos para no perder la técnica.", "Baja la barra con control (fase excéntrica) y sube con fuerza (fase concéntrica), sin rebotar la barra en el pecho.", "Respira: inhala al bajar y exhala al subir la barra.", "Ante cargas altas, usa una barra de seguridad o un compañero que te asegure, y nunca retires las manos de la barra con peso aún colgado."]', technique_url = 'https://www.youtube.com/watch?v=7aQY3u0Dk-Q' WHERE name = 'Press banca';
UPDATE exercises SET steps = '["Asegura tus piernas bajo los rodillos de un banco declinado (entre 15 y 30 grados) y tumba la espalda y la cabeza fijas.", "Estabiliza los hombros retrayendo las escápulas y arqueando ligeramente la zona media, plataforma estable para la barra.", "Agarra la barra algo más ancha que los hombros y descuélgala hasta el pecho inferior, situándola sobre la zona media baja.", "Baja la barra con control hasta la parte media o inferior del pecho, manteniendo la trayectoria perpendicular al pecho inclinado.", "Empuja la barra hacia arriba hasta extender los codos, siguiendo el recorrido desde la parte inferior del pecho.", "Mantén codos a unos 45 grados del torso y los hombros estables durante todo el movimiento.", "Respira con calma: inhala al bajar y exhala al subir."]', technique_url = 'https://www.youtube.com/watch?v=NNz3_wUMrvI' WHERE name = 'Press banca declinado';
UPDATE exercises SET steps = '["Ajusta el banco a una inclinación de 30 a 45 grados y siéntate con los pies apoyados en el suelo.", "Agarra la barra con un agarre algo más ancho que los hombros, retrae las escápulas y descuélgala sobre el pecho superior.", "Baja la barra controlada hasta la parte alta del pecho, justo bajo la clavícula, con codos hacia abajo y algo pegados al torso.", "Empuja la barra hacia arriba y ligeramente atrás, hasta situarla sobre la línea de los ojos al final del recorrido.", "Mantén el torso estable y la zona media activa, sin arquear excesivamente la espalda ni abrir los codos en exceso.", "Evita convertir el ejercicio en un press de hombros: el ángulo del banco se respeta con codos por debajo del plano horizontal.", "Respira de forma controlada e inhala al bajar y exhala al empujar."]', technique_url = 'https://www.youtube.com/watch?v=vUMtItXfO8Y' WHERE name = 'Press banca inclinado';
UPDATE exercises SET steps = '["Tiéndete en un banco plano con los ojos bajo la barra, los pies firmes en el suelo y los omóplatos retraídos.", "Agarra la barra con las manos más juntas que el ancho de los hombros (una o dos anchos de palma), con agarre prono.", "Desengancha la barra y colócala sobre el pecho, con los codos pegados al torso.", "Inhala y baja la barra de forma controlada hasta tocar el pecho, manteniendo los codos cerca del cuerpo.", "Exhala y empuja la barra hacia arriba hasta extender los codos por completo, sin rebotarla en el pecho.", "No separes los codos hacia los lados ni eleves la cadera del banco durante el recorrido."]', technique_url = 'https://www.youtube.com/watch?v=bnzaGiAyYVg' WHERE name = 'Press cerrado';
UPDATE exercises SET steps = '["Túmbate en el banco con los pies apoyados en el suelo y las mancuernas a la altura del pecho.", "Agarra las mancuernas con las palmas mirando hacia los pies y los codos a unos 45-60 grados del tronco.", "Empuja las mancuernas hacia arriba hasta extender por completo los codos, sin chocarlas entre sí.", "Baja las mancuernas con control hasta la altura del pecho.", "Mantén los omóplatos retraídos, el pecho alto y los pies plantados en todo el recorrido.", "No dejes caer las mancuernas: controla la fase excéntrica en todas las repeticiones."]', technique_url = 'https://www.youtube.com/watch?v=Lp9LLEGJJrI' WHERE name = 'Press con mancuerna en banco';
UPDATE exercises SET steps = '["Siéntate en el banco con una mancuerna en cada pierna y ayuda a subirlas a la posición de press usando el muslo.", "Túmbate con los pies en el suelo, la espalda pegada al banco y las mancuernas a la altura del pecho, con palmas hacia los pies.", "Empuja ambas mancuernas hacia arriba hasta extender los codos, en línea con los hombros y sin chocarlas en la parte superior.", "Baja las mancuernas en un arco controlado, abriendo ligeramente los codos, y siente el estiramiento del pecho en la parte baja.", "Mantén las muñecas firmes y rectas sobre las palmas, y los hombros retraídos contra el banco.", "El movimiento es profundo y controlado, baja hasta sentir un buen estiramiento sin dolor y sube sin bloquear los codos agresivamente.", "Respira: inhala al bajar y exhala al empujar."]', technique_url = 'https://www.youtube.com/watch?v=jWnGhz1f5D4' WHERE name = 'Press con mancuernas';
UPDATE exercises SET steps = '["Ajusta el asiento de la máquina para que las asas queden a la altura de la parte media del pecho.", "Sujeta las asas con agarre en prono y la espalda bien apoyada, con los pies firmes en el suelo y el torso pegado al respaldo.", "Empuja las asas hacia delante con fuerza hasta extender los codos, sin bloquearlos del todo.", "Baja las asas de vuelta de forma controlada hasta sentir un buen estiramiento del pecho, sin que la espalda se despegue del respaldo.", "Mantén los hombros bajos, sin que se adelanten ni se encolen en el empuje, y los codos a una altura estable.", "Respira de forma controlada: exhala al empujar e inhala al volver."]', technique_url = 'https://www.youtube.com/watch?v=v4XTkt2CURc' WHERE name = 'Press de pecho en máquina';
UPDATE exercises SET steps = '["Tiéndete en un banco plano y agarra la barra Z con agarre supino, con las manos a la altura de los hombros.", "Extiende los codos para llevar la barra sobre el pecho, con los brazos verticales y perpendiculares al cuerpo.", "Inhala y, sin mover los codos, flexiona los antebrazos para bajar la barra hacia la frente.", "Baja hasta unos centímetros de la frente o hasta sentir un estiramiento claro del tríceps, manteniendo los codos apuntando hacia arriba.", "Exhala y extiende los codos para volver a la posición inicial, sin balancear la barra ni abrir los codos.", "Mantén la espalda y las caderas apoyadas en el banco durante todo el recorrido."]', technique_url = 'https://www.youtube.com/watch?v=dRIdjDmkggY' WHERE name = 'Press francés';
UPDATE exercises SET steps = '["Ajusta el banco a 30-45 grados y siéntate con cada mancuerna sobre el muslo, sujetándolas firmemente.", "Impúlsate con la pierna para llevar las mancuernas a la altura de los hombros, con las palmas hacia los pies y la espalda pegada al banco.", "Empuja ambas mancuernas hacia arriba y ligeramente hacia el centro, sin girar el torso y la cadera quedan bien asentadas.", "Baja las mancuernas con control hasta la parte alta del pecho, manteniendo los codos algo por debajo del plano de los hombros.", "Alinea los hombros con el ángulo del banco y evita que el movimiento se convierta en press de hombros.", "Elige un peso que permita recorrido completo y rango de movimiento sin dolor.", "Respira de forma controlada: inhala al bajar y exhala al empujar."]', technique_url = 'https://www.youtube.com/watch?v=MkMf308jXww' WHERE name = 'Press inclinado con mancuernas';
UPDATE exercises SET steps = '["Colócate de pie con la barra apoyada en los deltoides y un agarre ligeramente más ancho que los hombros.", "Tensa el core y los glúteos, con los pies a la anchura de las caderas y las rodillas firmes.", "Empuja la barra verticalmente hacia arriba hasta extender por completo los brazos sobre la cabeza.", "Mantén el tronco recto y evita arquear la lumbar mientras la barra pasa por delante de la cara.", "Baja la barra con control hasta los deltoides, respirando durante el descenso.", "No hagas rebotes ni uses el impulso de las rodillas para completar la subida."]', technique_url = 'https://www.youtube.com/watch?v=j_Buh54Sb-w' WHERE name = 'Press militar de pie';
UPDATE exercises SET steps = '["Siéntate en el banco y ajusta el respaldo a un ángulo de entre 70 y 90 grados.", "Apoya los pies firmes en el suelo y sujeta el peso a la altura de los hombros con un agarre ligeramente ancho.", "Tensa el core y pega la espalda al respaldo antes de iniciar el movimiento.", "Empuja el peso hacia arriba hasta extender por completo los codos sin levantar los glúteos ni arquear la lumbar.", "Baja el peso con control hasta la altura de los hombros.", "Controla el descenso y evita el rebote en la posición baja."]', technique_url = 'https://www.youtube.com/watch?v=o5M9RZ-vWrc' WHERE name = 'Press militar sentado';
UPDATE exercises SET steps = '["Túmbate boca arriba sobre una esterilla con las rodillas flexionadas y los pies apoyados al ancho de las caderas.", "Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.", "Activa el core y pega la espalda baja al suelo.", "Empuja con los talones y eleva las caderas apretando los glúteos.", "En la parte alta, el cuerpo debe formar una línea recta desde los hombros hasta las rodillas.", "Mantén la posición uno o dos segundos sin arquear la espalda baja.", "Baja las caderas de forma controlada hasta el suelo y repite."]', technique_url = 'https://www.youtube.com/watch?v=yj_dwycxeos' WHERE name = 'Puente de glúteo';
UPDATE exercises SET steps = '["Túmbate transversalmente en un banco plano con la parte superior de la espalda y los hombros apoyados en el banco, con los pies bien firmes en el suelo.", "Agarra una mancuerna con las dos manos bajo el disco, por el lado inferior, y llévala sobre el pecho con los codos ligeramente flexionados.", "Baja la mancuerna lentamente en arco por detrás de la cabeza, doblando algo los codos, hasta sentir un estiramiento controlado en el pecho y el dorsal.", "No dejes que la mancuerna descienda más allá del rango cómodo y mantén el arco lumbar pegado a la zona media, cuidando la espalda.", "Tira con el pecho y los dorsales llevando la mancuerna de nuevo hasta la posición sobre el pecho, manteniendo los codos fijos.", "Evita el impulso con la cadera: el movimiento ocurre con los brazos y un torso laxo pero suelto, los codos semiflexionados.", "Respira de forma controlada: inhala al bajar detrás y exhala al volver sobre el pecho."]', technique_url = 'https://www.youtube.com/watch?v=5XO5KyDUAbE' WHERE name = 'Pullover con mancuerna';
UPDATE exercises SET steps = '["Colócate frente a la polea alta y agarra la barra con las manos separadas a la anchura de los hombros.", "Da un paso atrás para tensar el cable y separa los pies a la anchura de los hombros.", "Inclina ligeramente el tronco hacia delante y mantén una flexión suave y fija de los codos.", "Baja la barra trazando un arco desde la cabeza hasta la altura de los muslos, con los brazos casi rectos.", "Aprieta los dorsales al final del arco manteniendo el pecho alto y sin redondear la espalda.", "Vuelve a subir la barra siguiendo el mismo arco con control, sin mover el tronco ni cambiar la flexión de los codos."]', technique_url = 'https://www.youtube.com/watch?v=-UrSFw0QPHs' WHERE name = 'Pullover en polea';
UPDATE exercises SET steps = '["Colócate de pie con la barra apoyada en los deltoides y un agarre ligeramente más ancho que los hombros.", "Flexiona ligeramente rodillas y caderas con el core tenso para generar impulso.", "Extiende con energía las piernas y transfiere el impulso a los hombros para empujar la barra hacia arriba.", "Extiende por completo los brazos sobre la cabeza con el tronco recto y el core firme.", "Baja la barra con control hasta los deltoides acompañando la caída con las rodillas.", "Mantén el movimiento coordinado y evita arquear la lumbar o cargar el impulso en la espalda."]', technique_url = 'https://www.youtube.com/watch?v=yH5eKiYzPcA' WHERE name = 'Push press';
UPDATE exercises SET steps = '["Siéntate en el banco con el torso inclinado hacia delante y las mancuernas por debajo de las rodillas.", "Deja los brazos hacia el suelo con los codos ligeramente flexionados y las palmas enfrentadas.", "Abre las mancuernas lateralmente en arco hasta la altura de los hombros.", "Mantén la flexión de los codos constante y el torso estable durante el recorrido.", "Junta los omóplatos en la parte alta y evita subir con impulso.", "Baja con control hasta la posición inicial y mantén la tensión en toda la serie."]', technique_url = 'https://www.youtube.com/watch?v=OpHqGI6A1bY' WHERE name = 'Pájaros';
UPDATE exercises SET steps = '["Colócate de pie con los pies a la altura de las caderas y las rodillas ligeramente flexionadas, con la barra delante de ti.", "Dobla las caderas enviando el glúteo hacia atrás con la espalda recta hasta que el torso quede inclinado unos 45 grados, la barra colgando bajo los hombros.", "Agarra la barra con un agarre algo más ancho que los hombros, en prono, y mantén la columna neutra durante todo el movimiento.", "Tira de la barra hacia el abdomen, llevando los codos hacia atrás junto al torso, hasta rozar la zona media y juntando las escápulas.", "Baja la barra de forma controlada hasta los brazos extendidos sin redondear la espalda ni perder tensión.", "Mantén el cuerpo estabilizado y el abdomen firme para evitar movimientos violentos del torso, y no rebotes de la cadera.", "Respira: exhala al tirar e inhala al bajar la barra."]', technique_url = 'https://www.youtube.com/watch?v=qsbJcaAneaw' WHERE name = 'Remo con barra';
UPDATE exercises SET steps = '["Colócate con piernas y cadera en posición de flexión profunda, con la espalda recta y la barra en el suelo.", "Agarra la barra con las manos separadas a la altura de los hombros, y con la espalda firme, tira de la barra pegado a la espinilla hasta despegarla del suelo.", "Tira de la barra con fuerza hacia la parte baja del pecho y estómago, con los codos altos y por detrás de la espalda, y lleva las escápulas juntas.", "Baja la barra de forma controlada hasta el suelo en cada repetición, manteniendo la posición del torso (espalda casi paralela al suelo).", "No levantes la cadera para ayudarte: el torso se mantiene fijo y el movimiento se genera con la espalda y los brazos.", "No rebotes la barra en el suelo; cada repetición es un movimiento limpio y controlado desde el descanso.", "Respira: inhala al bajar y exhala al tirar de la barra."]', technique_url = 'https://www.youtube.com/watch?v=bVDRhgzoaGk' WHERE name = 'Remo con barra Pendlay';
UPDATE exercises SET steps = '["Apoya la mano y la rodilla derechas en un banco y coloca el pie izquierdo en el suelo, con la espalda recta.", "Sujeta la mancuerna con la mano izquierda, con el brazo extendido hacia el suelo y la palma mirando al cuerpo.", "Tira de la mancuerna hacia la cadera, llevando el codo hacia arriba y atrás, hasta retraer bien la escápula sin girar el torso.", "Baja la mancuerna de forma controlada hasta extender el brazo, sintiendo el estiramiento del dorsal.", "Mantén la espalda recta y el abdomen firme, en la posición inicial: no balancees la cadera ni el torso durante el movimiento.", "Completa las repeticiones con ese brazo y cambia de lado para trabajar ambos lados de igual forma.", "Respira: exhala al tirar e inhala al bajar la mancuerna."]', technique_url = 'https://www.youtube.com/watch?v=Vvnw0EYAlgc' WHERE name = 'Remo con mancuerna a una mano';
UPDATE exercises SET steps = '["Siéntate en la máquina y ajusta el asiento para que el agarre quede a la altura del pecho.", "Coloca los pies en los reposapiés y aprieta el pecho contra el apoyo con la espalda recta.", "Agarra las asas con las palmas enfrentadas o neutras, según el modelo de la máquina.", "Tira de las asas hacia el pecho llevando los codos hacia atrás y juntando los omóplatos.", "Estira los brazos de forma controlada hasta la posición inicial sin dejar que el peso te arranque los hombros.", "Mantén el tronco pegado al apoyo y evita balancearte o ayudar con el impulso de las piernas."]', technique_url = 'https://www.youtube.com/watch?v=rGeBwjJC8nU' WHERE name = 'Remo en máquina';
UPDATE exercises SET steps = '["Siéntate en la máquina de remo con los pies apoyados en los soportes y las rodillas ligeramente flexionadas.", "Agarra el asa con las palmas enfrentadas, sentado erguido, con la espalda recta y los brazos extendidos.", "Tira del asa hacia el abdomen, llevando los codos hacia atrás junto al torso y juntando las escápulas al final del recorrido.", "Extiende lentamente los brazos permitiendo que el torso bascule ligeramente hacia delante, manteniendo la espalda recta y el abdomen activo.", "Mantén la posición sin arquear excesivamente la espalda baja en el tirón; el movimiento se genera con las escápulas y los dorsales.", "No conviertas el movimiento en un ir y venir rápido de todo el cuerpo; la espalda permanece firme y el rango de repetición es completo.", "Respira: exhala al tirar e inhala al extender los brazos."]', technique_url = 'https://www.youtube.com/watch?v=JtTusrYzAos' WHERE name = 'Remo en polea sentado';
UPDATE exercises SET steps = '["Arrodíllate en el suelo con la cadera alineada sobre las rodillas y sostén la rueda con ambas manos.", "Coloca la rueda bajo los hombros, con la espalda neutra y el abdomen contraído.", "Rueda lentamente hacia delante extendiendo los brazos, manteniendo el tronco recto sin arquear la espalda.", "Continúa hacia delante en el rango que controles, sin hundir la cadera ni dejar que toque el suelo.", "Detente antes de perder la posición neutra de la espalda y contrae el abdomen con fuerza.", "Tira de la rueda hacia atrás usando el abdomen, guiándola con los brazos, hasta volver a la posición inicial.", "Desciende para arrodillarte en lugar de estar de pie si pierdes el control en cualquier momento."]', technique_url = 'https://www.youtube.com/watch?v=76uV2p-733k' WHERE name = 'Rueda abdominal';
UPDATE exercises SET steps = '["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados, con el torso ligeramente inclinado hacia atrás.", "Sujeta un disco o una balón medicinal con ambas manos delante del pecho y levanta ligeramente los pies del suelo para más intensidad.", "Mantén la espalda recta y el pecho elevado durante todo el ejercicio.", "Gira el torso hacia un lado llevando el peso junto a la zona de la cadera.", "Vuelve al centro y gira hacia el lado contrario, controlando el movimiento en lugar de balancear.", "Exhala en cada giro y mantén los brazos semiflexionados y estables.", "Realiza las repeticiones alternando lados de forma continua y con la espalda siempre neutra."]', technique_url = 'https://www.youtube.com/watch?v=hdSyLWfRJHc' WHERE name = 'Russian twist';
UPDATE exercises SET steps = '["Ponte de espaldas a un banco y apoya el empeine de un pie en el banco, con la otra pierna adelantada.", "Coloca el pie delantero a una distancia que permita que la rodilla quede sobre el talón al bajar.", "Baja flexionando la rodilla delantera hasta que el muslo quede casi paralelo al suelo, manteniendo el torso ligeramente inclinado.", "Mantén la rodilla delantera alineada con el pie y no la dejes colapsar hacia dentro.", "Empuja con el pie delantero para subir hasta la posición inicial sin apoyarte en la pierna trasera.", "Completa todas las repeticiones con una pierna y luego cambia de lado; si es difícil, apoya el pie trasero solo en la punta."]', technique_url = 'https://www.youtube.com/watch?v=6d6HlPWgAUs' WHERE name = 'Sentadilla búlgara';
UPDATE exercises SET steps = '["Colócate de pie con los pies al ancho de los hombros y los brazos relajados.", "Baja a una sentadilla flexionando caderas y rodillas, con la espalda neutra y el pecho erguido.", "Balancea los brazos hacia atrás mientras bajas para preparar el impulso.", "Empuja con fuerza contra el suelo y extiende por completo las caderas, rodillas y tobillos para saltar.", "Despega con el cuerpo extendido y los brazos impulsando hacia arriba.", "Aterriza con las puntas de los pies y amortigua flexionando las rodillas y las caderas.", "Repite el salto con una cadencia continua, manteniendo las rodillas alineadas y sin bloquear la espalda."]', technique_url = 'https://www.youtube.com/watch?v=2VoHEWxXG4s' WHERE name = 'Sentadilla con salto';
UPDATE exercises SET steps = '["Coloca la barra sobre la parte anterior de los hombros, sobre los deltoides, y mantén los codos altos para sujetarla sin clavarla en el cuello.", "Separa los pies al ancho de los hombros con las puntas ligeramente hacia fuera y aprieta el abdomen con la espalda neutra.", "Inhala y baja flexionando caderas y rodillas a la vez, manteniendo el torso lo más erguido posible.", "Baja hasta que los muslos queden paralelos al suelo o la movilidad lo permita, sin redondear la zona lumbar.", "Mantén los codos elevados y la barra estable durante todo el movimiento.", "Exhala y sube empujando con todo el pie hasta extender las rodillas, sin bascular el torso hacia delante."]', technique_url = 'https://www.youtube.com/watch?v=KXhu0HkJ7K4' WHERE name = 'Sentadilla frontal';
UPDATE exercises SET steps = '["Colócate de pie con los pies al ancho de los hombros y las puntas ligeramente hacia fuera.", "Sujeta una mancuerna o kettlebell con ambas manos a la altura del pecho, pegada al cuerpo.", "Activa el core, mantén la espalda neutra y el pecho erguido.", "Empuja las caderas hacia atrás y flexiona las rodillas bajando el cuerpo como si fueras a sentarte.", "Desciende hasta que los muslos queden al menos paralelos al suelo o hasta donde mantengas la espalda neutra.", "Mantén las rodillas alineadas con los pies y los talones apoyados en todo momento.", "Empuja el suelo con el pie entero y extiende las caderas y las rodillas para subir a la posición inicial.", "Exhala al subir, manten una cadencia controlada y sin rebotar en el fondo."]', technique_url = 'https://www.youtube.com/watch?v=AgD7XRyH05o' WHERE name = 'Sentadilla goblet';
UPDATE exercises SET steps = '["Coloca la barra sobre la parte alta de la espalda, sobre el trapecio, y agárrala con las manos separadas.", "Separa los pies al ancho de los hombros con las puntas ligeramente hacia fuera y aprieta la espalda en posición neutra, con el pecho erguido.", "Inhala y baja flexionando caderas y rodillas a la vez, como si fueras a sentarte, empujando las caderas hacia atrás.", "Baja hasta que los muslos queden paralelos al suelo o la movilidad lo permita, manteniendo la zona lumbar neutra.", "Mantén las rodillas alineadas con los dedos de los pies y las caderas por encima de ellas, sin que colapsen hacia dentro.", "Exhala y sube empujando con todo el pie hasta extender las rodillas y volver a la posición inicial.", "No dejes que las rodillas se junten ni que el peso se vaya hacia los dedos de los pies."]', technique_url = 'https://www.youtube.com/watch?v=xkcMxMf1X9A' WHERE name = 'Sentadilla trasera';
UPDATE exercises SET steps = '["Túmbate boca arriba con las rodillas flexionadas en un ángulo de 45 grados y los pies apoyados en el suelo.", "Cruza los brazos sobre el pecho o colócalos a los lados de la cabeza sin entrelazar los dedos.", "Contrae el abdomen y despega el torso del suelo vertebral por vertebral.", "Continúa subiendo hasta quedar sentado con el pecho hacia las rodillas, sin usar el impulso ni tirar del cuello.", "Desciende lentamente, desenrollando la espalda hasta apoyarla de nuevo en el suelo.", "Exhala al subir e inhala al bajar, manteniendo la cadera y los pies fijos en todo momento.", "Repite las repeticiones indicadas con un ritmo controlado y constante."]', technique_url = 'https://www.youtube.com/watch?v=oUpADVmt9W8' WHERE name = 'Sit-up';
UPDATE exercises SET steps = '["Túmbate boca arriba con las rodillas dobladas y los pies apoyados en el suelo, separados a la anchura de los hombros.", "Extiende los brazos a los costados del cuerpo, con las palmas hacia abajo.", "Eleva los hombros y la cabeza del suelo, contrayendo el abdomen con la mirada ligeramente hacia arriba.", "Inclina el tronco hacia un lado y toca el talón del mismo lado con la mano.", "Vuelve al centro sin soltar la contracción y toca el talón del lado contrario.", "Alterna los toques de lado a lado de forma continua, manteniendo la cadera apoyada y fuerte.", "Realiza las repeticiones indicadas sin descansar en la posición superior y con la mirada al frente."]', technique_url = 'https://www.youtube.com/watch?v=oFRhXxUZYnk' WHERE name = 'Toque de talones';
UPDATE exercises SET steps = '["Ponte de pie con la espalda recta y separa los pies al ancho de las caderas, con una mancuerna en cada mano o la barra sobre la espalda.", "Da un paso largo hacia delante y baja el cuerpo flexionando ambas rodillas.", "Baja hasta que la rodilla delantera forme un ángulo de 90 grados y la rodilla trasera casi toque el suelo.", "Mantén el torso recto y la rodilla delantera alineada con el pie, sin que sobrepase la punta de forma excesiva.", "Empuja con el pie delantero, apoyado en el talón, para volver a la posición inicial.", "Alterna las piernas en cada repetición manteniendo la cadera estable y sin balancearte."]', technique_url = 'https://www.youtube.com/watch?v=Xcfs_3DMKlc' WHERE name = 'Zancadas';
